function v4Modal(id,title){let m=document.getElementById(id);if(!m){m=document.createElement('div');m.className='modal';m.id=id;m.innerHTML=`<div class="modal-head"><strong>${esc(title)}</strong><button class="icon-btn" data-close-modal="${id}" aria-label="Cerrar">${UI.close}</button></div><div class="modal-body"></div>`;document.body.append(m)}return m}
async function customerRpc(action,data={}){if(!supabaseClient||!customerSession)throw Error('Inicia sesión.');const r=await supabaseClient.rpc('catalog_customer',{p_action:action,p_data:data});if(r.error)throw r.error;return r.data}
function syncAdminVisibility(){const b=document.getElementById('adminBtn');const allowed=!!adminSession&&(!!panelAccess.master||panelAccess.owner||panelAccess.modules.length>0);b.hidden=!allowed;b.style.display=allowed?'':'none';b.setAttribute('aria-hidden',String(!allowed));}
function clearCustomerState(){customerSerial++;customerSession=null;customerProfile=null;customerAddresses=[];avatarDraft='';accountError='';adminSession=null;panelAccess={owner:false,master:false,modules:[]};panelEpoch++;pendingCloudModules.clear();clearTimeout(cloudSyncTimer);state.orders=[];checkout.name='';checkout.phone='';checkout.callPhone='';checkout.address='';checkout.lat=checkout.lng=null;checkout.distance=checkout.shipping=0;checkout.savedAddressId='';orderRequestId='';sessionStorage.removeItem('foodCatalog.orderRequestId');lastPdfBlob=null;lastOrderId=null;lastQuote=null;publicQuoteSerial++;addressEditorSerial++;saveLocal();for(const id of ['adminModal','customerProfileModal','foodAddressModal','summaryModal']){const m=document.getElementById(id);if(m){closeModal(id);if(!['summaryModal','adminModal'].includes(id))m.querySelector('.modal-body')?.replaceChildren()}}document.getElementById('adminTabs').replaceChildren();document.getElementById('adminContent').replaceChildren();syncAdminVisibility();renderAccountButton();if(publicFoodPin){publicFoodMap.removeLayer(publicFoodPin);publicFoodPin=null}if(publicFoodRoute){publicFoodMap.removeLayer(publicFoodRoute);publicFoodRoute=null}document.getElementById('foodDestination').value='';document.getElementById('foodQuote').textContent='Utiliza tu ubicación para localizar el establecimiento.';renderSavedAddressShortcut()}
adminSignOut=async function(){clearCustomerState();if(supabaseClient){const {error}=await supabaseClient.auth.signOut();if(error){toast(error.message,'error');return}}toast('Sesión cerrada.','ok')};
panelVerify=async function(){panelAccess={owner:false,master:false,modules:[]};syncAdminVisibility();if(!supabaseClient||!adminSession)return false;const who=adminSession.user.id,epoch=customerSerial;const {data,error}=await supabaseClient.auth.getUser();if(error||!data?.user||adminSession?.user.id!==who||epoch!==customerSerial)return false;try{const r=await supabaseClient.rpc('catalog_panel',{p_action:'access',p_payload:{}});if(r.error)throw r.error;if(adminSession?.user.id!==who||epoch!==customerSerial)return false;panelAccess={owner:false,master:false,modules:[],...r.data};}catch{}syncAdminVisibility();return panelAccess.master||panelAccess.owner||panelAccess.modules.length>0};
