function renderAccountButton(){let b=document.getElementById('customerAccountBtn');if(!b){b=document.createElement('button');b.id='customerAccountBtn';b.className='icon-btn';document.getElementById('adminBtn').before(b);b.onclick=()=>{renderCustomerProfile();openModal('customerProfileModal')}}b.title=customerSession?'Mi cuenta':'Iniciar sesión o crear cuenta';b.setAttribute('aria-label',b.title);b.innerHTML=customerProfile?.avatar?`<img class="customer-avatar" src="${esc(customerProfile.avatar)}" alt="Perfil">`:CUSTOMER_ICON;syncAdminVisibility()}
async function customerAuthChanged(session){const serial=++customerSerial,previous=customerSession?.user.id;customerSession=session||null;adminSession=session||null;if(!session){clearCustomerState();return}if(previous&&previous!==session.user.id){state.orders=[];customerProfile=null;customerAddresses=[];checkout.address='';checkout.lat=checkout.lng=null;orderRequestId='';sessionStorage.removeItem('foodCatalog.orderRequestId')}panelAccess={owner:false,master:false,modules:[]};renderAccountButton();try{await panelVerify();if(serial!==customerSerial)return;await refreshSiteStatus();if(serial!==customerSerial)return;const r=await customerRpc('me');if(serial!==customerSerial)return;customerProfile=r.profile;customerAddresses=r.addresses||[];avatarDraft=customerProfile.avatar||'';accountError='';checkout.name=customerProfile.full_name||session.user.user_metadata?.full_name||session.user.user_metadata?.name||'';checkout.phone=customerProfile.phone||'';checkout.callPhone=customerProfile.call_phone||'';}catch(e){if(serial!==customerSerial)return;accountError=e.message}if(serial!==customerSerial)return;renderAccountButton();renderSavedAddressShortcut();if(document.getElementById('customerProfileModal')?.classList.contains('show'))renderCustomerProfile();}
