const v4Init=initSupabase;initSupabase=async function(){await v4Init();if(!supabaseClient)return;supabaseClient.auth.onAuthStateChange((event,session)=>{if(!session||event==='SIGNED_OUT'){clearCustomerState();return}setTimeout(()=>{if(event==='PASSWORD_RECOVERY'){customerAuthView='update';customerSession=session;adminSession=session;renderCustomerProfile();openModal('customerProfileModal')}else customerAuthChanged(session)},0)});const {data}=await supabaseClient.auth.getSession();await customerAuthChanged(data?.session);await refreshSiteStatus();};
openAdmin=async function(){if(await panelVerify()){renderAdmin();openModal('adminModal')}else{customerAuthView='login';renderCustomerProfile();openModal('customerProfileModal')}};
function authPassword(){const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#_-';let s='';const bytes=crypto.getRandomValues(new Uint8Array(40));for(const n of bytes)if(n<Math.floor(256/alphabet.length)*alphabet.length&&s.length<18)s+=alphabet[n%alphabet.length];return s.length===18?s:authPassword()}
function renderCustomerProfile(){const m=v4Modal('customerProfileModal','Mi cuenta'),host=m.querySelector('.modal-body');m.classList.toggle('auth-mode',!customerSession||customerAuthView==='update');if(!customerSession||customerAuthView==='update'){drawCustomerAuth(host);return}host.innerHTML=`<div class="profile-heading">${customerProfile?.avatar?`<img src="${esc(customerProfile.avatar)}" class="profile-photo" alt="Perfil">`:CUSTOMER_ICON}<div><h3>${esc(customerProfile?.full_name||customerSession.user.user_metadata?.full_name||'Mi cuenta')}</h3><p class="small muted">${esc(customerSession.user.email||'')}</p></div></div>${accountError?`<p class="notice">${esc(accountError)}</p>`:''}<div class="toolbar">${panelAccess.master||panelAccess.owner||panelAccess.modules.length?panelButton('accountAdmin','Panel de administración',UI.settings):''}${panelButton('accountOrders','Mis reservaciones',UI.orders,'secondary')}${panelButton('accountLogout','Cerrar sesión',UI.lock,'ghost')}</div>${siteStatus&&!siteStatus.active?`<div class="notice"><strong>Suscripción del sitio ${siteStatus.suspended?'suspendida':'vencida'}</strong><p>${esc(siteStatus.payment_instructions||'Contacta al creador para renovar el sitio.')}</p><p>Periodo de 30 días: ${money(siteStatus.price)}</p></div>`:''}<div class="section-card"><h3>Mi perfil</h3><div class="admin-grid two">${panelField('profileFullName','Nombre completo',customerProfile?.full_name||checkout.name)}${panelField('profilePhone','WhatsApp a 10 dígitos',customerProfile?.phone||'','tel')}${panelField('profileCallPhone','Teléfono de llamadas a 10 dígitos',customerProfile?.call_phone||'','tel')}<label class="field">Foto de perfil<input class="input" id="profilePhoto" type="file" accept="image/png,image/jpeg,image/webp"></label></div><div class="toolbar">${panelButton('profileSave','Guardar perfil')}${panelButton('profileRemovePhoto','Quitar foto',UI.trash,'ghost')}</div></div><div class="section-card"><h3>Mis domicilios</h3><div id="profileAddresses">${customerAddresses.map(a=>`<article class="saved-address"><div><strong>${esc(a.label)}${a.is_default?' · Predeterminado':''}</strong><p class="small">${esc(addressText(a))}</p><p class="small muted">${esc(a.reference_text)}</p></div><div class="toolbar"><button class="icon-btn" data-use-address="${a.id}" aria-label="Usar domicilio">${UI.pin}</button><button class="icon-btn" data-edit-address="${a.id}" aria-label="Editar domicilio">${UI.edit}</button><button class="icon-btn" data-delete-address="${a.id}" aria-label="Eliminar domicilio">${UI.trash}</button></div></article>`).join('')||'<p class="small muted">Guarda Casa, Trabajo u otros destinos.</p>'}</div>${panelButton('profileAddAddress','Añadir domicilio',UI.plus,'secondary')}</div><div id="accountOrderList"></div>`;
 document.getElementById('accountLogout').onclick=adminSignOut;document.getElementById('accountAdmin')?.addEventListener('click',()=>{closeModal(m.id);openAdmin()});document.getElementById('profileAddAddress').onclick=()=>openFoodAddressEditor();document.getElementById('profilePhoto').onchange=async e=>{try{if(e.target.files[0]){avatarDraft=await panelReadImage(e.target.files[0]);if(avatarDraft.length>400000)throw Error('Reduce el tamaño de la imagen.');toast('Foto preparada. Pulsa Guardar perfil.','ok')}}catch(err){toast(err.message,'error')}};document.getElementById('profileRemovePhoto').onclick=()=>{avatarDraft='';toast('Pulsa Guardar perfil para quitar la foto.','info')};document.getElementById('profileSave').onclick=e=>panelRun(e.currentTarget,async()=>{const userId=customerSession.user.id;const r=await customerRpc('profile_save',{full_name:document.getElementById('profileFullName').value.trim(),phone:document.getElementById('profilePhone').value.replace(/\D/g,''),call_phone:document.getElementById('profileCallPhone').value.replace(/\D/g,''),avatar:avatarDraft});if(customerSession?.user.id!==userId)return;customerProfile=r.profile;customerAddresses=r.addresses;checkout.name=customerProfile.full_name;checkout.phone=customerProfile.phone;checkout.callPhone=customerProfile.call_phone;renderAccountButton();renderCustomerProfile()},'Perfil guardado.');host.querySelectorAll('[data-edit-address]').forEach(b=>b.onclick=()=>openFoodAddressEditor(customerAddresses.find(a=>a.id===b.dataset.editAddress)));host.querySelectorAll('[data-use-address]').forEach(b=>b.onclick=async()=>{closeModal(m.id);await useFoodAddress(b.dataset.useAddress)});host.querySelectorAll('[data-delete-address]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este domicilio?'))panelRun(b,async()=>{const userId=customerSession.user.id;const r=await customerRpc('address_delete',{id:b.dataset.deleteAddress});if(customerSession?.user.id!==userId)return;customerAddresses=r.addresses;renderCustomerProfile();renderSavedAddressShortcut()})});document.getElementById('accountOrders').onclick=async e=>panelRun(e.currentTarget,async()=>{const serial=customerSerial,rows=await customerRpc('orders');if(serial!==customerSerial)return;const target=document.getElementById('accountOrderList');target.innerHTML=`<div class="section-card"><h3>Mis reservaciones</h3>${rows.map(o=>`<article class="saved-address"><div><strong>${esc(o.folio)} · ${money(o.total)}</strong><p class="small">${esc(new Date(o.created_at).toLocaleString('es-MX'))} · ${esc(ticketPaymentLabel(o.payment_status))} · ${esc(o.status)}</p><p class="small">${esc(o.delivery_address||'Recoger en el local')}</p></div><button class="icon-btn" data-my-pdf="${o.id}" aria-label="Descargar ticket">${UI.download}</button></article>`).join('')||'<p>Todavía no tienes pedidos asociados a esta cuenta.</p>'}</div>`;target.querySelectorAll('[data-my-pdf]').forEach(b=>b.onclick=()=>panelRun(b,async()=>{const order=cloudOrderToState(rows.find(o=>o.id===b.dataset.myPdf));ticketDownload(await panelBuildTicket(order,ticketConfig(state.config.ticket)),'pedido-'+order.folio+'.pdf')}))});}
function drawCustomerAuth(host){const signup=customerAuthView==='signup',recover=customerAuthView==='recover',update=customerAuthView==='update';host.innerHTML=`<div class="auth-intro">${CUSTOMER_ICON}<h3>${update?'Nueva contraseña':recover?'Recuperar acceso':'Tu cuenta de comida'}</h3><p class="small muted">Guarda tu perfil y domicilios para tus próximos pedidos.</p></div>${!recover&&!update?`<div class="auth-tabs"><button class="btn ${signup?'secondary':''}" data-auth-view="login">Iniciar sesión</button><button class="btn ${signup?'':'secondary'}" data-auth-view="signup">Crear cuenta</button></div>${panelButton('foodGoogle','Continuar con Google',GOOGLE_ICON,'secondary full')}<p class="auth-divider small muted">O utiliza tu correo</p>`:''}<form id="foodAuthForm">${signup?panelField('authName','Nombre completo'):''}${!update?panelField('authEmail','Correo electrónico','','email'):''}${!recover?`${panelField('authPass',update?'Nueva contraseña':'Contraseña','','password')}${signup||update?`${panelField('authConfirm','Confirmar contraseña','','password')}${panelButton('authGenerate','Generar contraseña',UI.refresh,'secondary')}`:''}`:''}<p class="small" id="foodAuthStatus" role="status"></p><button id="foodAuthSubmit" class="btn full" type="submit">${UI.lock}<span>${recover?'Enviar enlace':update?'Guardar contraseña':signup?'Crear mi cuenta':'Iniciar sesión'}</span></button></form>${panelButton('authRecover','¿Olvidaste tu contraseña?',UI.lock,'ghost full')}${recover?'<button class="btn ghost full" data-auth-view="login">Volver a iniciar sesión</button>':''}`;
 host.querySelectorAll('[data-auth-view]').forEach(b=>b.onclick=()=>{customerAuthView=b.dataset.authView;renderCustomerProfile()});document.getElementById('authRecover').onclick=()=>{customerAuthView='recover';renderCustomerProfile()};document.getElementById('authGenerate')?.addEventListener('click',()=>{const pass=authPassword();document.getElementById('authPass').value=pass;document.getElementById('authPass').type='text';document.getElementById('authConfirm').value=pass;document.getElementById('foodAuthStatus').textContent='Guarda esta contraseña en tu gestor antes de continuar.'});const redirect=location.origin+location.pathname;
 document.getElementById('foodGoogle')?.addEventListener('click',async e=>panelRun(e.currentTarget,async()=>{if(!supabaseClient)throw Error('Espera a que conecte Supabase.');const r=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:redirect}});if(r.error)throw r.error}));document.getElementById('foodAuthForm').onsubmit=async e=>{e.preventDefault();if(customerAuthBusy)return;const serial=customerSerial,b=document.getElementById('foodAuthSubmit'),out=document.getElementById('foodAuthStatus');customerAuthBusy=true;b.disabled=true;try{if(!supabaseClient)throw Error('Espera a que conecte Supabase.');const email=document.getElementById('authEmail')?.value.trim(),password=document.getElementById('authPass')?.value;if(signup||update){if(password.length<12||password.length>128||password!==document.getElementById('authConfirm').value)throw Error('Usa de 12 a 128 caracteres y confirma la contraseña.')}if(signup&&(!document.getElementById('authName').value.trim()||document.getElementById('authName').value.trim().length>200))throw Error('Escribe tu nombre completo (máximo 200 caracteres).');let r;if(recover){r=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:redirect});if(r.error)throw r.error;out.textContent='Si el correo corresponde a una cuenta, recibirás un enlace para recuperar el acceso.';return}if(update){r=await supabaseClient.auth.updateUser({password});if(r.error)throw r.error;customerAuthView='login';renderCustomerProfile();toast('Contraseña actualizada.','ok');return}r=signup?await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:redirect,data:{full_name:document.getElementById('authName').value.trim()}}}):await supabaseClient.auth.signInWithPassword({email,password});if(r.error)throw r.error;if(r.data.session){customerAuthView='login';window.v22AuthSync?.(r.data.session);await customerAuthChanged(r.data.session);renderCustomerProfile()}else{document.getElementById('authPass').value='';if(document.getElementById('authConfirm'))document.getElementById('authConfirm').value='';out.textContent='Revisa tu correo para confirmar tu cuenta antes de iniciar sesión.'}}catch(err){if(out.isConnected)out.textContent=err.message}finally{customerAuthBusy=false;if(b.isConnected)b.disabled=false}};}
function addressText(a){return `${a.street} ${a.number}, ${a.colony}, ${a.municipality}, ${a.state}${a.postal_code?', CP '+a.postal_code:''}`}
async function openFoodAddressEditor(a){if(!customerSession){renderCustomerProfile();openModal('customerProfileModal');return}const serial=++addressEditorSerial,user=customerSession.user.id,m=v4Modal('foodAddressModal','Domicilio de entrega'),host=m.querySelector('.modal-body');let point=a?{lat:a.lat,lng:a.lng}:null;host.innerHTML=`<p class="small muted">Busca la calle o utiliza tu ubicación y ajusta el pin a la entrada.</p><div class="toolbar">${panelButton('addressGps','Mi ubicación',UI.pin,'secondary')}${panelButton('addressFind','Buscar calle',UI.search,'secondary')}</div><div class="admin-grid two">${[['label','Nombre del domicilio',a?.label||'Casa'],['street','Calle',a?.street||''],['number','Número o S/N',a?.number||''],['colony','Colonia',a?.colony||''],['postal_code','Código postal',a?.postal_code||''],['municipality','Municipio',a?.municipality||'Manzanillo'],['state','Estado',a?.state||'Colima'],['references','Referencias',a?.reference_text||'']].map(([id,label,value])=>panelField('address_'+id,label,value)).join('')}</div><div class="map address-editor-map" id="foodAddressMap"></div><p id="addressPointStatus" class="small">${point?'Pin guardado; puedes ajustarlo.':'Marca la entrada de tu domicilio.'}</p><label class="row"><input type="checkbox" id="addressDefault" ${a?.is_default||!customerAddresses.length?'checked':''}>Usar como predeterminado</label>${panelButton('addressSave','Guardar y usar domicilio',UI.save,'full')}`;openModal(m.id);let pin;const current=()=>serial===addressEditorSerial&&customerSession?.user.id===user;const choose=(lat,lng)=>{if(!current())return;point={lat,lng};if(pin)pin.setLatLng([lat,lng]);else if(publicAddressMap){pin=L.marker([lat,lng],{draggable:true}).addTo(publicAddressMap);pin.on('dragend',e=>choose(e.target.getLatLng().lat,e.target.getLatLng().lng))}document.getElementById('addressPointStatus').textContent=`Pin: ${lat.toFixed(6)}, ${lng.toFixed(6)}`};setTimeout(()=>{if(!current()||!host.isConnected||!m.classList.contains('show'))return;if(publicAddressMap)publicAddressMap.remove();if(typeof L==='undefined'){document.getElementById('addressPointStatus').textContent='No cargó el mapa. Revisa la conexión.';return}const o=point||state.config.origin;publicAddressMap=L.map('foodAddressMap',{rotate:true,touchRotate:true,dragRotate:true,shiftKeyRotate:true,rotateControl:{position:"topright",behavior:"reset",closeOnZeroBearing:false}}).setView([o.lat,o.lng],15);addConfiguredTileLayer(publicAddressMap,'foodAddressMap');publicAddressMap.on('click',e=>choose(e.latlng.lat,e.latlng.lng));if(point)choose(point.lat,point.lng)},100);
 document.getElementById('addressGps').onclick=e=>panelRun(e.currentTarget,async()=>{const p=await foodGps();if(current()){choose(p.coords.latitude,p.coords.longitude);publicAddressMap?.setView([point.lat,point.lng],18);document.getElementById('addressPointStatus').textContent+=` · Precisión ${Math.round(p.coords.accuracy)} m`}});document.getElementById('addressFind').onclick=e=>panelRun(e.currentTarget,async()=>{const query=['street','colony','municipality','state'].map(k=>document.getElementById('address_'+k).value).join(', ');const p=await foodSearch(query);if(current()){choose(p.lat,p.lng);publicAddressMap?.setView([p.lat,p.lng],17)}});document.getElementById('addressSave').onclick=e=>panelRun(e.currentTarget,async()=>{if(!point)throw Error('Marca la entrada en el mapa.');if(!current())throw Error('Vuelve a abrir el domicilio.');const data={id:a?.id||'',...Object.fromEntries(['label','street','number','colony','postal_code','municipality','state','references'].map(k=>[k,document.getElementById('address_'+k).value.trim()])),...point,is_default:document.getElementById('addressDefault').checked};const r=await customerRpc('address_save',data);if(!current())return;customerAddresses=r.addresses;const saved=customerAddresses.find(x=>a?x.id===a.id:x.label===data.label&&x.lat===data.lat&&x.lng===data.lng);closeModal(m.id);renderCustomerProfile();renderSavedAddressShortcut();if(saved)await useFoodAddress(saved.id)},'Domicilio guardado.');}
function foodGps(){return window.vibraPrecisePosition()}
async function foodSearch(query){if(query.trim().length<3)throw Error('Escribe una calle o dirección.');const r=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=mx&q='+encodeURIComponent(query),{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('La búsqueda de direcciones no respondió. Marca el pin.');const data=await r.json();if(!data.length)throw Error('No se encontró la dirección. Marca el pin.');return {lat:Number(data[0].lat),lng:Number(data[0].lon),address:data[0].display_name}}
function renderSavedAddressShortcut(){const host=document.getElementById('foodSavedAddresses');if(!host)return;host.innerHTML=customerSession?`<div class="address-picker-row"><label class="field">Selecciona un domicilio guardado<select class="select" id="foodSavedSelect"><option value="">Seleccionar domicilio</option>${customerAddresses.map(a=>`<option value="${a.id}" ${checkout.savedAddressId===a.id?'selected':''}>${esc(a.label)}${a.is_default?' · Predeterminado':''}</option>`).join('')}</select></label>${panelButton('foodNewAddress','Guardar domicilio',UI.pin,'secondary')}</div>`:`<button class="btn secondary" id="foodLoginAddresses">${CUSTOMER_ICON}<span>Inicia sesión para guardar domicilios</span></button>`;document.getElementById('foodSavedSelect')?.addEventListener('change',e=>e.target.value&&useFoodAddress(e.target.value));document.getElementById('foodNewAddress')?.addEventListener('click',()=>openFoodAddressEditor());document.getElementById('foodLoginAddresses')?.addEventListener('click',()=>{renderCustomerProfile();openModal('customerProfileModal')})}
async function useFoodAddress(id){const a=customerAddresses.find(x=>x.id===id);if(!a)return;checkout.savedAddressId=id;checkout.address=addressText(a);checkout.notes=a.reference_text||checkout.notes;checkout.delivery='delivery';document.getElementById('foodDestination').value=checkout.address;await chooseFoodDestination(a.lat,a.lng);renderSavedAddressShortcut();if(document.getElementById('cartDrawer').classList.contains('show'))renderCart()}
function labeledFoodPin(kind){return L.divIcon({className:'food-map-pin',html:`<span>${kind==='origin'?'Local':'Entrega'}</span>${FOOD.pin}`,iconSize:[44,56],iconAnchor:[22,52]})}
function initFoodPublicMap(){if(typeof L==='undefined')return;const host=document.getElementById('foodPublicMap');if(!host||publicFoodMap)return;const o=state.config.origin;publicFoodMap=L.map(host,{rotate:true,touchRotate:true,dragRotate:true,shiftKeyRotate:true,rotateControl:{position:"topright",behavior:"reset",closeOnZeroBearing:false}}).setView([o.lat,o.lng],13);addConfiguredTileLayer(publicFoodMap,'foodPublicMap');publicFoodOrigin=L.marker([o.lat,o.lng],{icon:labeledFoodPin('origin'),bubblingMouseEvents:false}).addTo(publicFoodMap).bindPopup('Local: '+esc(state.config.businessName));publicFoodMap.on('click',e=>chooseFoodDestination(e.latlng.lat,e.latlng.lng).catch(err=>toast(err.message,'error')));publicFoodMap.invalidateSize()}
